    short_hi = 128;
    wide_min = -2147483648;
    wide_max = 2147483647;
    level = 1;
    level_hi = 9;
    in_i8 = -1;
    in_i16 = -32768;
    in_i32 = 2147483647;
    b8 = 0;
    b16 = 0;
    b32 = 0;
    b64 = 0;
    nothing = 0;
    all_on = -9223372034707292159;
